        if not isinstance(piece, VersionPiece):
            raise ValueError("pieces must be a list of VersionPiece objects")

        # Append the piece to the output using the style
        if style == "release":
            output += piece.release
        elif style == "version":
            output += piece.version
        elif style == "both":
